import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Teachers() {
  const [teachers, setTeachers] = useState([]);

  useEffect(() => {
    // 🟢 ඩේටාබේස් එකෙන් ගුරුවරුන්ගේ විස්තර ගන්නවා
    axios.get('http://localhost:8081/api/view-teachers')
      .then(res => setTeachers(res.data))
      .catch(err => console.error("Error fetching teachers:", err));
  }, []);

  // 🟢 නමේ මුල් අකුරු දෙක ගන්න ෆන්ක්ෂන් එක (උදා: Charaka Dikwella -> CD)
  const getInitials = (name) => {
    if (!name) return "AP";
    const parts = name.split(' ');
    if (parts.length >= 2) {
      return (parts[0][0] + parts[1][0]).toUpperCase();
    }
    return name.substring(0, 2).toUpperCase();
  };

  return (
    <div style={{ padding: '50px', backgroundColor: '#f8fafc', minHeight: '100vh', textAlign: 'center' }}>
      <h2 style={{ color: '#15803d', fontSize: '32px', marginBottom: '10px' }}>Meet Our Expert Lecturers</h2>
      <p style={{ color: '#64748b', marginBottom: '40px' }}>Highly Qualified Panel of Teachers at Aura Pen Education</p>
      
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '30px', maxWidth: '1200px', margin: '0 auto' }}>
        {teachers.map(teacher => (
          <div key={teacher.id} style={{ backgroundColor: 'white', borderRadius: '15px', overflow: 'hidden', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', textAlign: 'left' }}>
            <div style={{ backgroundColor: '#dcfce7', height: '150px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <h1 style={{ color: '#15803d', fontSize: '70px', margin: 0 }}>{getInitials(teacher.name)}</h1>
            </div>
            <div style={{ padding: '25px' }}>
              <span style={{ backgroundColor: '#eff6ff', color: '#3b82f6', padding: '5px 12px', borderRadius: '20px', fontSize: '12px', fontWeight: 'bold' }}>{teacher.subject}</span>
              <h3 style={{ margin: '15px 0 5px 0', color: '#1e293b' }}>{teacher.name}</h3>
              <p style={{ margin: '0 0 15px 0', color: '#64748b', fontSize: '14px' }}>🎓 {teacher.qualifications || 'Professional Lecturer'}</p>
              <p style={{ margin: '5px 0', color: '#475569', fontSize: '14px' }}>📧 Email: {teacher.email || 'Not Provided'}</p>
              <p style={{ margin: '5px 0', color: '#475569', fontSize: '14px' }}>📞 Contact: {teacher.phone_number}</p>
              <p style={{ margin: '15px 0 0 0', color: '#10b981', fontSize: '12px', fontWeight: 'bold' }}>✓ Aura Pen Verified Lecturer</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
